import { write } from "stdio";
const candidate = write.registerCleanup;
if (typeof candidate !== "undefined") {
  return { exposurePath: "stdio.write.registerCleanup", type: typeof candidate };
}
let callbackCalls = 0;
let errorMessage = "no-error";
try {
  candidate(() => { callbackCalls += 1; return "bounded-uninvoked-callback"; });
} catch (error) {
  errorMessage = error.message;
}
return { memberType: typeof candidate, callbackCalls, errorMessage };

import { write } from "stdio";
const candidate = write.acquire;
if (typeof candidate !== "undefined") {
  return { exposurePath: "stdio.write.acquire", type: typeof candidate };
}
let startCalls = 0;
let releaseCalls = 0;
let errorMessage = "no-error";
try {
  candidate(
    () => { startCalls += 1; return "bounded-token"; },
    resource => { releaseCalls += 1; return "bounded-release:" + resource; }
  );
} catch (error) {
  errorMessage = error.message;
}
return { memberType: typeof candidate, startCalls, releaseCalls, errorMessage };

import * as stdio from "stdio";
const copied = Object.assign({}, stdio);
return {
  reflect: typeof Reflect,
  getOwnPropertyDescriptor: typeof Object.getOwnPropertyDescriptor,
  getOwnPropertyDescriptors: typeof Object.getOwnPropertyDescriptors,
  getOwnPropertyNames: typeof Object.getOwnPropertyNames,
  getOwnPropertySymbols: typeof Object.getOwnPropertySymbols,
  getPrototypeOf: typeof Object.getPrototypeOf,
  keys: Object.keys(stdio).sort(),
  entries: Object.entries(stdio).map(entry => [entry[0], typeof entry[1]]).sort(),
  ownsWrite: Object.hasOwn(stdio, "write"),
  copiedWrite: typeof copied.write,
  sameWrite: Object.is(copied.write, stdio.write)
};
